// ─────────────────────────────────────────────────────────────
// NODE: "Normalize Input"   (Code node · Run Once for All Items)
// Cleans what the website sent so every later step can rely on it.
// It does NOT decide whether the order is valid — "Process Order" does.
// ─────────────────────────────────────────────────────────────
const body = $input.first().json.body ?? {};
const customer = body.customer ?? {};
const clean = (v) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ') : '');

// Merge repeated products (2 lines of the same mouse → 1 line, qty 2)
const merged = {};
let blankLines = 0;
for (const line of Array.isArray(body.items) ? body.items : []) {
  const id = clean(String(line?.productId ?? '')).toLowerCase();
  if (!id) { blankLines++; continue; }
  merged[id] = (merged[id] ?? 0) + Number(line?.quantity);   // NaN is caught in Process Order
}
const items = Object.entries(merged).map(([productId, quantity]) => ({ productId, quantity }));

// A fingerprint of the cart, used to spot accidental double submissions
const signature = items.map((i) => `${i.productId}:${i.quantity}`).sort().join('|');

return [{
  json: {
    name: clean(customer.name),
    email: clean(customer.email).toLowerCase(),
    phone: clean(customer.phone),
    items,
    blank_lines: blankLines,
    product_ids: items.map((i) => i.productId),
    signature,
    received_at: new Date().toISOString(),
    raw: body,
  },
}];

// ─────────────────────────────────────────────────────────────
// NODE: "Process Order"   (Code node · Run Once for All Items)
// All business rules live here, in plain deterministic code:
//   validation → pricing from the DATABASE → 5% bonus rule →
//   review checks → customer type → tags → order reference.
// No AI is involved in any number or status.
// ─────────────────────────────────────────────────────────────
const BONUS_THRESHOLD = 500000;      // ₦500,000
const BONUS_RATE = 0.05;             // 5% store credit
const MAX_QTY_PER_ITEM = 5;          // above this → manual review
const UNUSUAL_ORDER_VALUE = 10000000; // ₦10m → manual review
const VIP_LIFETIME_PAID = 3000000;   // ₦3m paid in total → VIP
const VIP_PAID_ORDERS = 3;           // or 3+ paid orders → VIP

const input = $('Normalize Input').first().json;
const productRows = $('Get Products').first().json.products ?? [];
const history = $('Get Customer History').first().json ?? {};

const errors = [];    // missing/invalid info  → INCOMPLETE_ORDER
const warnings = [];  // valid but suspicious  → REVIEW_REQUIRED
const tags = new Set();

// ── 1. Validate customer details ─────────────────────────────
if (input.name.length < 2) errors.push('Customer name is missing');
else if (input.name.length > 80 || /\d/.test(input.name)) errors.push('Customer name looks invalid');

if (!input.email) errors.push('Email address is missing');
else if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(input.email)) errors.push('Email address is invalid');

// Nigerian mobile numbers: 0803…, +234803…, 234803…  → stored as +234803…
let phone = null;
const digits = input.phone.replace(/[^\d+]/g, '');
const local = digits.replace(/^\+?234/, '').replace(/^0/, '');
if (!input.phone) errors.push('Phone number is missing');
else if (!/^[789][01]\d{8}$/.test(local)) errors.push('Phone number must be a valid Nigerian mobile number');
else phone = '+234' + local;

// ── 2. Validate and price the items (prices come from the database) ──
const products = Object.fromEntries(productRows.map((p) => [p.id, p]));
if (input.items.length === 0) errors.push('No products in the order');
if (input.blank_lines > 0) errors.push('One or more order lines had no product');

const lines = [];
for (const { productId, quantity } of input.items) {
  const p = products[productId];
  if (!p || p.active === false) { errors.push(`Unknown product: ${productId}`); continue; }
  if (!Number.isInteger(quantity) || quantity < 1) { errors.push(`Invalid quantity for ${p.name}`); continue; }

  const unitPrice = Number(p.price);
  lines.push({
    product_id: p.id,
    product_name: p.name,
    quantity,
    unit_price: unitPrice,
    line_total: unitPrice * quantity,
  });

  // ── 3. Review checks (inventory + suspicious patterns) ──
  if (quantity > Number(p.stock)) {
    warnings.push(`Only ${p.stock} × ${p.name} in stock, customer requested ${quantity}`);
    tags.add('INSUFFICIENT_STOCK');
  }
  if (quantity > MAX_QTY_PER_ITEM) {
    warnings.push(`Unusually large quantity: ${quantity} × ${p.name}`);
    tags.add('UNUSUAL_QUANTITY');
  }
}

const totalAmount = lines.reduce((sum, l) => sum + l.line_total, 0);
const totalQuantity = lines.reduce((sum, l) => sum + l.quantity, 0);

// ── 4. Promotional bonus rule (₦500,000+ → 5%, pending until paid) ──
//    An incomplete order can't be paid, so it earns no bonus.
const bonusEligible = errors.length === 0 && totalAmount >= BONUS_THRESHOLD;
const bonusAmount = bonusEligible ? Math.round(totalAmount * BONUS_RATE) : 0;

// ── 5. More review checks using the customer's history ──
if (totalAmount > UNUSUAL_ORDER_VALUE) {
  warnings.push(`Order value above ₦${UNUSUAL_ORDER_VALUE.toLocaleString('en-NG')}`);
  tags.add('UNUSUAL_ORDER_VALUE');
}
if (Number(history.recent_duplicates) > 0) {
  warnings.push('Same customer submitted the same items in the last 10 minutes (possible duplicate)');
  tags.add('POSSIBLE_DUPLICATE');
}
if (phone && history.last_phone && history.last_phone !== phone) {
  warnings.push(`Phone number differs from this customer's previous order (${history.last_phone})`);
  tags.add('DETAILS_MISMATCH');
}

// ── 6. Customer type ──
const previousOrders = Number(history.previous_orders ?? 0);
let customerType = 'NEW_CUSTOMER';
if (previousOrders > 0) customerType = 'RETURNING_CUSTOMER';
if (Number(history.lifetime_paid ?? 0) >= VIP_LIFETIME_PAID || Number(history.paid_orders ?? 0) >= VIP_PAID_ORDERS) {
  customerType = 'VIP_CUSTOMER';
}

// ── 7. Route, statuses and tags ──
let route, orderStatus;
if (errors.length > 0) {
  route = 'incomplete';
  orderStatus = 'INCOMPLETE';
  tags.clear();               // review tags don't matter until the info is complete
  tags.add('INCOMPLETE_ORDER');
} else if (warnings.length > 0) {
  route = 'review';
  orderStatus = 'UNDER_REVIEW';
  tags.add('REVIEW_REQUIRED');
} else {
  route = 'valid';
  orderStatus = 'RECEIVED';
}
if (route !== 'incomplete') {
  tags.add(bonusEligible ? 'HIGH_VALUE_ORDER' : 'STANDARD_ORDER');
  tags.add(customerType);
}
tags.add('PAYMENT_PENDING');  // an order submission is NEVER a payment

// ── 8. Unique order reference: VE-YYYYMMDD-XXXXX (Lagos date) ──
const lagosDate = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Lagos' }).replace(/-/g, '');
const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I to avoid confusion
let suffix = '';
for (let i = 0; i < 5; i++) suffix += alphabet[Math.floor(Math.random() * alphabet.length)];
const orderRef = `VE-${lagosDate}-${suffix}`;

// Tag order: classification first, then status, then extras
const order = ['INCOMPLETE_ORDER', 'HIGH_VALUE_ORDER', 'STANDARD_ORDER', 'REVIEW_REQUIRED', 'PAYMENT_PENDING'];
const sortedTags = [...tags].sort((a, b) => {
  const ia = order.indexOf(a), ib = order.indexOf(b);
  return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
});

return [{
  json: {
    route,                                  // valid | review | incomplete
    order_ref: orderRef,
    customer_name: input.name || null,
    customer_email: input.email || null,
    customer_phone: phone ?? (input.phone || null),
    items: lines,
    items_summary: lines.map((l) => `${l.product_name} × ${l.quantity}`).join(', ') || null,
    total_quantity: totalQuantity,
    total_amount: totalAmount,
    bonus_eligible: bonusEligible,
    bonus_amount: bonusAmount,
    bonus_status: bonusEligible ? 'PENDING_PAYMENT' : 'NOT_ELIGIBLE',
    payment_status: 'PAYMENT_PENDING',
    order_status: orderStatus,
    customer_type: route === 'incomplete' ? null : customerType,
    tags: sortedTags,
    errors,
    warnings,
    items_signature: input.signature,
    received_at: input.received_at,
    raw_payload: input.raw,
  },
}];

// ─────────────────────────────────────────────────────────────
// NODE: "Compose Messages"   (Code node · Run Once for All Items)
// Builds the customer email, the Telegram alert, the website
// response and the database record — all from the computed order.
// Wording never claims payment or bonus activation (both pending).
// ─────────────────────────────────────────────────────────────
const SITE_URL = 'https://YOUR-STORE.vercel.app';   // ← change to your deployed site URL

const o = $input.first().json;
const naira = (n) => '₦' + Number(n).toLocaleString('en-NG');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const firstName = (o.customer_name || 'there').split(' ')[0];
const placedAt = new Date(o.received_at).toLocaleString('en-NG', {
  timeZone: 'Africa/Lagos', dateStyle: 'medium', timeStyle: 'short',
});
const payUrl = `${SITE_URL}/pay/${o.order_ref}`;

// ── Human-readable statuses for the customer ──
const statusText = {
  RECEIVED: 'Received, awaiting payment',
  UNDER_REVIEW: 'Received, being checked by our team',
  INCOMPLETE: 'Incomplete',
}[o.order_status];
const paymentText = 'Not yet paid. We have not received a payment for this order.';

// ── Bonus paragraph ──
const bonusHtml = o.bonus_eligible
  ? `<p style="background:#ecfdf3;border:1px solid #abefc6;border-radius:8px;padding:12px 14px;margin:16px 0;">
       <strong>Promotional bonus: ${naira(o.bonus_amount)} store credit (pending)</strong><br>
       Your order is ${naira(o.total_amount)}, so it qualifies for our 5% store-credit bonus on orders of ₦500,000 or more.
       The bonus is <strong>pending</strong> and will only be activated after your payment has been verified.
     </p>`
  : `<p style="color:#555;margin:16px 0;">
       Promotional bonus: not eligible for this order. Orders of ₦500,000 or more earn a 5% store-credit bonus.
     </p>`;

// ── Next steps differ by route ──
const nextStepsHtml = o.route === 'valid'
  ? `<p><strong>Next step:</strong> complete your payment securely with Paystack.</p>
     <p><a href="${payUrl}" style="display:inline-block;background:#0f172a;color:#fff;text-decoration:none;padding:12px 20px;border-radius:8px;font-weight:600;">Pay ${naira(o.total_amount)} now</a></p>
     <p style="color:#555;font-size:14px;">We will email you again as soon as your payment is verified.</p>`
  : `<p><strong>Next step:</strong> please <strong>do not make a payment yet</strong>. Our team needs to check one or more items in your order before it can proceed.
     We will contact you by email or on ${esc(o.customer_phone)} once the check is complete.</p>`;

const rowsHtml = o.items.map((l) => `
  <tr>
    <td style="padding:8px;border-bottom:1px solid #eee;">${esc(l.product_name)}</td>
    <td style="padding:8px;border-bottom:1px solid #eee;text-align:center;">${l.quantity}</td>
    <td style="padding:8px;border-bottom:1px solid #eee;text-align:right;">${naira(l.unit_price)}</td>
    <td style="padding:8px;border-bottom:1px solid #eee;text-align:right;">${naira(l.line_total)}</td>
  </tr>`).join('');

const emailHtml = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;color:#111;line-height:1.5;">
  <h2 style="margin-bottom:4px;">VoltEdge Electronics</h2>
  <p style="color:#555;margin-top:0;">Order confirmation</p>
  <p>Hi ${esc(firstName)},</p>
  <p>Thank you for your order. Here are the details we received on ${placedAt}.</p>
  <table style="width:100%;border-collapse:collapse;font-size:14px;margin:16px 0;">
    <tr><td style="padding:4px 0;color:#555;">Order reference</td><td style="padding:4px 0;"><strong>${o.order_ref}</strong></td></tr>
    <tr><td style="padding:4px 0;color:#555;">Order status</td><td style="padding:4px 0;">${statusText}</td></tr>
    <tr><td style="padding:4px 0;color:#555;">Payment status</td><td style="padding:4px 0;">${paymentText}</td></tr>
  </table>
  <table style="width:100%;border-collapse:collapse;font-size:14px;">
    <tr style="background:#f5f5f5;">
      <th style="padding:8px;text-align:left;">Product</th><th style="padding:8px;">Qty</th>
      <th style="padding:8px;text-align:right;">Unit price</th><th style="padding:8px;text-align:right;">Subtotal</th>
    </tr>
    ${rowsHtml}
    <tr><td colspan="3" style="padding:8px;text-align:right;"><strong>Order total</strong></td>
        <td style="padding:8px;text-align:right;"><strong>${naira(o.total_amount)}</strong></td></tr>
  </table>
  ${bonusHtml}
  ${nextStepsHtml}
  <p>If anything above is wrong, simply reply to this email and quote <strong>${o.order_ref}</strong>.</p>
  <p>Thank you for shopping with VoltEdge Electronics.</p>
</div>`;

const emailSubject = o.route === 'valid'
  ? `Order ${o.order_ref} received: ${naira(o.total_amount)} awaiting payment`
  : `Order ${o.order_ref} received: our team is checking it`;

// ── Telegram alert for the team (HTML parse mode) ──
const header = {
  valid: '🛒 <b>New order</b>',
  review: '⚠️ <b>New order: REVIEW REQUIRED</b>',
  incomplete: '❌ <b>Incomplete order submission</b>',
}[o.route];

const tg = [
  `${header}  <code>${o.order_ref}</code>`,
  '',
  `<b>Customer:</b> ${esc(o.customer_name || '(missing)')}`,
  `<b>Email:</b> ${esc(o.customer_email || '(missing)')}`,
  `<b>Phone:</b> ${esc(o.customer_phone || '(missing)')}`,
  `<b>Items:</b> ${esc(o.items_summary || '(none valid)')}`,
  `<b>Total quantity:</b> ${o.total_quantity}`,
  `<b>Total value:</b> ${naira(o.total_amount)}`,
  `<b>Bonus:</b> ${o.bonus_eligible ? `${naira(o.bonus_amount)} (pending payment)` : 'Not eligible'}`,
  `<b>Payment:</b> ${o.payment_status}`,
  `<b>Order status:</b> ${o.order_status}`,
  o.customer_type ? `<b>Customer type:</b> ${o.customer_type}` : null,
  `<b>Tags:</b> ${o.tags.join(', ')}`,
];
if (o.errors.length) tg.push('', '<b>Missing / invalid:</b>', ...o.errors.map((e) => `• ${esc(e)}`));
if (o.warnings.length) tg.push('', '<b>Needs review:</b>', ...o.warnings.map((w) => `• ${esc(w)}`));
if (o.route === 'valid') tg.push('', 'No action needed until payment is confirmed.');

// ── Response the website shows the customer ──
const response = o.route === 'incomplete'
  ? { ok: false, orderRef: o.order_ref, errors: o.errors,
      message: 'We could not process your order. Please correct the details below and try again.' }
  : { ok: true, orderRef: o.order_ref, status: o.order_status, paymentStatus: o.payment_status,
      total: o.total_amount, bonus: o.bonus_amount, canPay: o.route === 'valid',
      message: o.route === 'valid'
        ? 'Order received. Check your email for confirmation and payment instructions.'
        : 'Order received. Our team will check it before payment. Please do not pay yet.' };

// ── Record for the database (create_order function) ──
const dbRecord = {
  order_ref: o.order_ref,
  customer_name: o.customer_name,
  customer_email: o.customer_email,
  customer_phone: o.customer_phone,
  items_summary: o.items_summary,
  total_quantity: o.total_quantity,
  total_amount: o.total_amount,
  bonus_amount: o.bonus_amount,
  bonus_status: o.bonus_status,
  payment_status: o.payment_status,
  order_status: o.order_status,
  tags: o.tags,
  warnings: [...o.errors, ...o.warnings],
  customer_type: o.customer_type,
  items_signature: o.items_signature,
  items: o.items,
  raw_payload: o.raw_payload,
};

return [{
  json: {
    ...o,
    email_subject: emailSubject,
    email_html: emailHtml,
    telegram_text: tg.filter((line) => line !== null).join('\n'),
    response,
    db_record: dbRecord,
  },
}];
